#!/usr/bin/env python3
"""T143: a very small 68000 assembler for the benches' synthetic programs, and the synthetic ROM images they run (no BIOS, no game: generated bytes).

A program is a list of (mnemonic, args) tuples built with the functions below; `assemble(origin, items)` returns the bytes. Only what the benches need:
move.b / move.w / move.l #imm,(abs).l   move.w (abs).l,Dn   bra label   label   dc.w   nop   moveq   lea (abs).l,An   move.w Dn,(abs).l

  python3 m68kasm.py selftest        encodings of every instruction against known words
"""
import struct
import sys


class Asm:
    def __init__(self, origin):
        self.origin = origin
        self.out = bytearray()
        self.labels = {}
        self.fix = []

    def pc(self):
        return self.origin + len(self.out)

    def w(self, v):
        self.out += struct.pack(">H", v & 0xFFFF)

    def l(self, v):
        self.out += struct.pack(">I", v & 0xFFFFFFFF)

    def label(self, n):
        self.labels[n] = self.pc()

    def nop(self):
        self.w(0x4E71)

    def move_b_imm_abs(self, imm, addr):
        self.w(0x13FC); self.w(imm & 0xFF); self.l(addr)

    def move_w_imm_abs(self, imm, addr):
        self.w(0x33FC); self.w(imm); self.l(addr)

    def move_l_imm_abs(self, imm, addr):
        self.w(0x23FC); self.l(imm); self.l(addr)

    def move_w_abs_dn(self, addr, dn):
        self.w(0x3039 | (dn << 9)); self.l(addr)

    def move_w_dn_abs(self, dn, addr):
        self.w(0x33C0 | dn); self.l(addr)

    def moveq(self, imm, dn):
        self.w(0x7000 | (dn << 9) | (imm & 0xFF))

    def addq_w(self, imm, dn):
        self.w(0x5040 | ((imm & 7) << 9) | dn)

    def move_w_dn_ind_an_postinc(self, dn, an):          # move.w Dn,(An)+
        self.w(0x30C0 | (an << 9) | dn)

    def lea_abs(self, addr, an):
        self.w(0x41F9 | (an << 9)); self.l(addr)

    def bra(self, label):
        self.w(0x6000)
        self.fix.append((len(self.out), label))
        self.w(0)                                          # 16 bit displacement

    def dbra(self, dn, label):
        self.w(0x51C8 | dn)
        self.fix.append((len(self.out), label))
        self.w(0)

    def bytes(self):
        o = bytearray(self.out)
        for pos, label in self.fix:
            disp = self.labels[label] - (self.origin + pos)
            struct.pack_into(">h", o, pos, disp)
        return bytes(o)


def selftest():
    a = Asm(0xC00100)
    a.move_w_imm_abs(0x0F00, 0x401FFE)
    assert a.bytes() == bytes.fromhex("33fc0f00" "00401ffe"), a.bytes().hex()
    a = Asm(0)
    a.move_b_imm_abs(0, 0x300001)
    assert a.bytes() == bytes.fromhex("13fc0000" "00300001")
    a = Asm(0x100)
    a.label("x"); a.nop(); a.bra("x")
    assert a.bytes() == bytes.fromhex("4e71" "6000fffc"), a.bytes().hex()
    a = Asm(0)
    a.moveq(5, 3); a.lea_abs(0x10F300, 0); a.move_w_dn_ind_an_postinc(3, 0); a.addq_w(1, 3)
    assert a.bytes() == bytes.fromhex("7605" "41f9" "0010f300" "30c3" "5243"), a.bytes().hex()
    print("m68kasm selftest: ok")


if __name__ == "__main__":
    if sys.argv[1:] == ["selftest"]:
        selftest()
